import math

def check_condition(n):
    """
    Checks if k^2 === 1 (mod n) for all k such that gcd(k, n) = 1.
    """
    if n < 2:
        return False

    # We only need to check k from 1 up to n-1
    for k in range(1, n):
        if math.gcd(k, n) == 1:
            # Check if k^2 is congruent to 1 modulo n
            if (k * k) % n != 1:
                return False
    return True

# Check for n from 2 to 30
satisfying_n = []
for n in range(2, 31):
    if check_condition(n):
        satisfying_n.append(n)

print("Values of n (2 <= n <= 30) that satisfy the condition:", satisfying_n)

